    XCTAssertEqual(current.unreadCount, 1)
    XCTAssertEqual(current.maxCount, 100)
  }

  func testBadgeRewardNotificationDecodesConcretePresentationWithoutBreakingLegacyKinds() throws {
    let data = Data(
      #"{"id":"00000000-0000-0000-0000-000000000012","kind":"badgeUnlocked","actor":{"id":"00000000-0000-0000-0000-000000000013","displayName":"Owner","joinedAt":0,"completedResultCount":1,"bestWPM":80},"badge":{"id":"swift-line","title":"迅捷一行","systemImage":"bolt"},"createdAt":0,"readAt":null}"#.utf8)
    let notification = try JSONDecoder().decode(RemoteNotification.self, from: data)

    XCTAssertEqual(notification.kind, .badgeUnlocked)
    XCTAssertEqual(notification.badge?.id, "swift-line")
    XCTAssertEqual(notification.presentationTitle, "已解锁徽章：迅捷一行")
    XCTAssertEqual(notification.presentationSystemImage, "bolt")

    let legacy = try JSONDecoder().decode(
      RemoteNotification.self,
      from: Data(
        #"{"id":"00000000-0000-0000-0000-000000000014","kind":"connectionRequest","actor":{"id":"00000000-0000-0000-0000-000000000015","displayName":"Friend","joinedAt":0,"completedResultCount":0,"bestWPM":0},"createdAt":0,"readAt":null}"#.utf8))
    XCTAssertEqual(legacy.presentationTitle, "Friend 想与你成为好友")
    XCTAssertEqual(legacy.presentationSystemImage, "person.badge.plus")

    let future = try JSONDecoder().decode(
      RemoteNotification.self,
      from: Data(
        #"{"id":"00000000-0000-0000-0000-000000000016","kind":"futureReward","actor":{"id":"00000000-0000-0000-0000-000000000017","displayName":"Future","joinedAt":0,"completedResultCount":0,"bestWPM":0},"createdAt":0,"readAt":null}"#.utf8))
    XCTAssertEqual(future.kind, .unknown)
    XCTAssertEqual(future.presentationTitle, "收到一条新通知")
    XCTAssertEqual(future.presentationSystemImage, "bell.fill")
  }

  func testRemoteAccountUserDefaultsLegacyServersToPasswordAndDecodesOAuthMethods() throws {
    let legacy = try JSONDecoder().decode(
      RemoteAccountUser.self,
      from: Data(
        #"{"id":"00000000-0000-0000-0000-000000000001","email":"legacy@example.com","displayName":"Legacy","totalExperience":8}"#
          .utf8))
    XCTAssertEqual(legacy.authenticationMethods, [.password])
    XCTAssertEqual(legacy.profileDetails, .init())
    XCTAssertTrue(legacy.availableBadges.isEmpty)
    XCTAssertNil(legacy.selectedBadgeID)
    XCTAssertNil(legacy.personalBestResetAt)

    let modern = try JSONDecoder().decode(
      RemoteAccountUser.self,
      from: Data(
        #"{"id":"00000000-0000-0000-0000-000000000002","email":"oauth@example.com","emailVerified":true,"displayName":"OAuth","totalExperience":12,"authenticationMethods":["google","password","discord"],"availableBadges":[{"id":"swift-line","title":"迅捷一行","systemImage":"bolt"}],"selectedBadgeID":"swift-line","personalBestResetAt":100,"profileDetails":{"bio":"Native first","keyboard":"ANSI","github":"typebar","socialHandle":"typist","websiteURL":"https://example.com","showActivity":false}}"#
          .utf8))
    XCTAssertTrue(modern.emailVerified)
    XCTAssertEqual(modern.authenticationMethods, [.google, .password, .discord])
    XCTAssertEqual(
      modern.profileDetails,
      .init(
        bio: "Native first", keyboard: "ANSI", github: "typebar", socialHandle: "typist",
        websiteURL: "https://example.com", showActivity: false))
    XCTAssertEqual(modern.availableBadges.map(\.id), ["swift-line"])
    XCTAssertEqual(modern.selectedBadgeID, "swift-line")
    XCTAssertEqual(modern.personalBestResetAt, Date(timeIntervalSinceReferenceDate: 100))

    let leaderboardEntry = try JSONDecoder().decode(
      RemoteLeaderboardEntry.self,
      from: Data(
        #"{"id":"00000000-0000-0000-0000-000000000003","rank":1,"userID":"00000000-0000-0000-0000-000000000002","displayName":"OAuth","mode":"time","language":"english","wpm":80,"accuracy":98,"consistency":99,"finishedAt":0,"selectedBadge":{"id":"swift-line","title":"迅捷一行","systemImage":"bolt"},"discordAvatar":{"subject":"123456789012345678","avatarHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}"#
          .utf8))
    XCTAssertEqual(leaderboardEntry.selectedBadge?.id, "swift-line")
    XCTAssertEqual(
      leaderboardEntry.discordAvatar?.cdnURL?.host,
      "cdn.discordapp.com")

    let legacyExperienceEntry = try JSONDecoder().decode(
      RemoteExperienceLeaderboardEntry.self,
      from: Data(
        #"{"id":"00000000-0000-0000-0000-000000000004","rank":1,"userID":"00000000-0000-0000-0000-000000000002","displayName":"OAuth","totalExperience":12}"#
          .utf8))
    XCTAssertNil(legacyExperienceEntry.selectedBadge)
  }

