  func testInactivityPolicyCountsIdleIntervalsAndInvalidatesTrailingIdleTimedTests() throws {
    let events = [start.addingTimeInterval(0.2), start.addingTimeInterval(2.2)]
    XCTAssertEqual(
      TestInactivityPolicy.intervalCounts(
        activityDates: events, startedAt: start, endedAt: start.addingTimeInterval(4.6),
        includesFractionalTail: true),
      [1, 0, 1, 0, 0])
    XCTAssertEqual(
      TestInactivityPolicy.inactiveDuration(
        activityDates: events, startedAt: start, endedAt: start.addingTimeInterval(4.6),
        includesFractionalTail: true),
      3)

    var idle = TypingSession(configuration: .timed(seconds: 10), prompt: "amber harbor")
    idle.insert("a", at: start)
    idle.tick(at: start.addingTimeInterval(10))
    let invalidResult = try XCTUnwrap(idle.result(at: start.addingTimeInterval(10)))
    XCTAssertEqual(idle.outcome, .invalidAFK)
    XCTAssertEqual(invalidResult.afkDuration, 9)
    XCTAssertEqual(invalidResult.engagedDuration, 1)
    XCTAssertEqual(invalidResult.afkPercentage, 90, accuracy: 0.000_001)
    XCTAssertEqual(idle.remainingSeconds(at: start.addingTimeInterval(10)), 0)
    XCTAssertFalse(ResultSavingPolicy.shouldPersist(outcome: invalidResult.outcome, enabled: true))
    XCTAssertEqual(
      invalidResult.outcome.statusText(savesResult: false), "本次因闲置无效 · 未保存为完成成绩")

    var active = TypingSession(configuration: .timed(seconds: 10), prompt: "amber harbor")
    active.insert("a", at: start)
    active.insert("m", at: start.addingTimeInterval(8))
    active.tick(at: start.addingTimeInterval(10))
    XCTAssertEqual(active.outcome, .completed)

    var keyboardOnly = TypingSession(configuration: .timed(seconds: 10), prompt: "amber harbor")
    keyboardOnly.insert("a", at: start)
    keyboardOnly.deleteBackward(at: start.addingTimeInterval(5))
    keyboardOnly.deleteBackward(at: start.addingTimeInterval(6))
    keyboardOnly.recordKeyboardActivity(at: start.addingTimeInterval(7))
    keyboardOnly.tick(at: start.addingTimeInterval(10))
    let keyboardOnlyResult = try XCTUnwrap(keyboardOnly.result())
    XCTAssertEqual(keyboardOnlyResult.afkDuration, 6)
  }

  func testAfkPercentageUsesTheCompletedWallClockDuration() {
    let result = CompletedTestResult(
      id: UUID(), configuration: .timed(seconds: 30), outcome: .completed, startedAt: start,
      finishedAt: start.addingTimeInterval(30), afkDuration: 7, typedCharacterCount: 50,
      correctCharacterCount: 48, errorCount: 2, wpm: 19, rawWpm: 20, accuracy: 96,
      restartCount: 3)
    XCTAssertEqual(result.afkPercentage, 23.333_333_333_3, accuracy: 0.000_001)
    XCTAssertEqual(result.restartCount, 3)

    let instant = CompletedTestResult(
      id: UUID(), configuration: .words(10), outcome: .completed, startedAt: start,
      finishedAt: start, afkDuration: 1, typedCharacterCount: 0, correctCharacterCount: 0,
      errorCount: 0, wpm: 0, rawWpm: 0, accuracy: 100)
    XCTAssertEqual(instant.afkPercentage, 0)
  }

  func testResultConsistencyRebuildsCadenceOnlyFromLocalReplay() {
    let steadyEvents: [TypingReplayEvent] = [
      .init(offset: 0.2, kind: .insert, text: "a"),
      .init(offset: 1.2, kind: .insert, text: "b"),
      .init(offset: 2.2, kind: .insert, text: "c"),
    ]
    let steady = ResultConsistencyPolicy.metrics(events: steadyEvents, duration: 3)
    XCTAssertEqual(steady.typing, 100)
    XCTAssertEqual(steady.key, 100)

    let uneven = ResultConsistencyPolicy.metrics(
      events: [
        .init(offset: 0.2, kind: .insert, text: "a"),
        .init(offset: 1.2, kind: .insert, text: "b"),
        .init(offset: 1.4, kind: .insert, text: "c"),
        .init(offset: 3.8, kind: .insert, text: "d"),
      ],
      duration: 4
    )
    XCTAssertLessThan(uneven.typing, steady.typing)
    XCTAssertLessThan(uneven.key, steady.key)

    let unavailable = ResultConsistencyPolicy.metrics(events: [], duration: 3)
    XCTAssertEqual(unavailable, .init(typing: 0, key: 0))
  }

  func testPhysicalKeyTimingsUseOnlyClosedNonRepeatEvents() throws {
    var session = TypingSession(configuration: .timed(seconds: 1), prompt: "amber")
    session.recordPhysicalKeyEvent(keyCode: 0, isKeyDown: true, isRepeat: false, at: start)
    session.insert("a", at: start.addingTimeInterval(0.01))
    session.recordPhysicalKeyEvent(
      keyCode: 0, isKeyDown: true, isRepeat: true, at: start.addingTimeInterval(0.03))
    session.recordPhysicalKeyEvent(
      keyCode: 0, isKeyDown: false, isRepeat: false, at: start.addingTimeInterval(0.1))
    session.recordPhysicalKeyEvent(
      keyCode: 9, isKeyDown: false, isRepeat: false, at: start.addingTimeInterval(0.15))
    session.recordPhysicalKeyEvent(
      keyCode: 1, isKeyDown: true, isRepeat: false, at: start.addingTimeInterval(0.2))
    session.recordPhysicalKeyEvent(
      keyCode: 1, isKeyDown: false, isRepeat: false, at: start.addingTimeInterval(0.4))
    session.recordPhysicalKeyEvent(
      keyCode: 2, isKeyDown: true, isRepeat: false, at: start.addingTimeInterval(0.8))
    session.recordPhysicalKeyEvent(
      keyCode: 3, isKeyDown: true, isRepeat: false, at: start.addingTimeInterval(0.9))
    session.tick(at: start.addingTimeInterval(1.01))

    let result = try XCTUnwrap(session.result(at: start.addingTimeInterval(1.01)))
    XCTAssertEqual(result.keyDurationSamples.count, 2)
    XCTAssertEqual(result.keyDurationSamples[0], 0.1, accuracy: 0.000_001)
    XCTAssertEqual(result.keyDurationSamples[1], 0.2, accuracy: 0.000_001)
    let stats = try XCTUnwrap(result.keyDurationStats)
    XCTAssertEqual(stats.averageMilliseconds, 150, accuracy: 0.000_001)
    XCTAssertEqual(stats.standardDeviationMilliseconds, 50, accuracy: 0.000_001)
    XCTAssertEqual(stats.sampleCount, 2)
    XCTAssertEqual(result.keyOverlapDuration, 0)

    session.recordPhysicalKeyEvent(
      keyCode: 2, isKeyDown: false, isRepeat: false, at: start.addingTimeInterval(1.1))
    session.recordPhysicalKeyEvent(
      keyCode: 3, isKeyDown: false, isRepeat: false, at: start.addingTimeInterval(1.2))
    XCTAssertEqual(
      try XCTUnwrap(session.result(at: start.addingTimeInterval(1.01))).keyDurationSamples.count,
      2)

    var overlap = TypingSession(configuration: .timed(seconds: 1), prompt: "amber")
    overlap.recordPhysicalKeyEvent(keyCode: 0, isKeyDown: true, isRepeat: false, at: start)
    overlap.insert("a", at: start)
    overlap.recordPhysicalKeyEvent(
      keyCode: 1, isKeyDown: true, isRepeat: false, at: start.addingTimeInterval(0.1))
    overlap.recordPhysicalKeyEvent(
      keyCode: 0, isKeyDown: false, isRepeat: false, at: start.addingTimeInterval(0.15))
    overlap.recordPhysicalKeyEvent(
      keyCode: 1, isKeyDown: false, isRepeat: false, at: start.addingTimeInterval(0.2))
    overlap.recordPhysicalKeyEvent(
      keyCode: 2, isKeyDown: true, isRepeat: false, at: start.addingTimeInterval(0.3))
    overlap.recordPhysicalKeyEvent(
      keyCode: 2, isKeyDown: false, isRepeat: false, at: start.addingTimeInterval(0.4))
    overlap.tick(at: start.addingTimeInterval(1))

    let overlapResult = try XCTUnwrap(overlap.result(at: start.addingTimeInterval(1)))
    XCTAssertEqual(overlapResult.keySpacingSamples.count, 2)
    XCTAssertEqual(overlapResult.keySpacingSamples[0], 0.1, accuracy: 0.000_001)
    XCTAssertEqual(overlapResult.keySpacingSamples[1], 0.2, accuracy: 0.000_001)
    let spacingStats = try XCTUnwrap(overlapResult.keySpacingStats)
    XCTAssertEqual(spacingStats.averageMilliseconds, 150, accuracy: 0.000_001)
    XCTAssertEqual(spacingStats.standardDeviationMilliseconds, 50, accuracy: 0.000_001)
    XCTAssertEqual(spacingStats.sampleCount, 2)
    XCTAssertEqual(overlapResult.keyOverlapDuration, 0.05, accuracy: 0.000_001)
  }

