    XCTAssertEqual(
      MinimumWordBurstPolicy.threshold(baseWpm: 100, mode: .flex, wordLength: 3), 100)
    XCTAssertEqual(
      MinimumWordBurstPolicy.threshold(baseWpm: 100, mode: .flex, wordLength: 9), 70)

