      ),
      (
        "Kuntem",
        ["`1234567890-=", "vlndkjwouq[]\\", "tsrhfgcaie;", "zxpb'my.,/"],
        ["~!@#$%^&*()_+", "VLNDKJWOUQ{}|", "TSRHFGCAIE:", "ZXPB\"MY><?"]
      ),
      (
        "kuntem-jq",
        ["`1234567890-=", "vlndkqwouj[]\\", "tsrhfgcaie;", "zxpb'my.,/"],
        ["~!@#$%^&*()_+", "VLNDKQWOUJ{}|", "TSRHFGCAIE:", "ZXPB\"MY><?"]
      ),
    ]

