      XCTAssertEqual(guideRows.map(\.count), [13, 12, 12, 11])
      for (keyCodes, guideRow) in zip(isoRows, guideRows) {
        for (keyCode, key) in zip(keyCodes, guideRow) {
          XCTAssertEqual(
