  func testIndexedLexiconPromptReadsOnlyTheRequestedNumberOfWords() {
    XCTAssertTrue(IndexedLexicon([]).isEmpty)
    XCTAssertTrue(TypingLanguage.english450k.supportsLocalWordFilter)
    XCTAssertFalse(TypingLanguage.mixedLanguages.supportsLocalWordFilter)
    XCTAssertFalse(TypingLanguage.codeSwift.supportsLocalWordFilter)

    var requestedIndices: [Int] = []
    let lexicon = IndexedLexicon(count: 450_029) { index in
      requestedIndices.append(index)
      return "typebar\(index)"
    }

    let prompt = StarterLexicon.prompt(
      tokens: 25, lexicon: lexicon, separator: " ", punctuation: ["."],
      contentOptions: ContentOptions(), usesZipfFrequency: false)

    XCTAssertEqual(prompt.split(separator: " ").count, 25)
    XCTAssertEqual(requestedIndices.count, 25)
    XCTAssertTrue(requestedIndices.allSatisfy { (0..<lexicon.count).contains($0) })

    let largestScalePrompt = StarterLexicon.prompt(
      wordCount: 25, language: .english450k, contentOptions: ContentOptions())
    XCTAssertEqual(largestScalePrompt.split(separator: " ").count, 25)
    let largestSpanishScalePrompt = StarterLexicon.prompt(
      wordCount: 25, language: .spanish650k, contentOptions: ContentOptions())
    XCTAssertGreaterThanOrEqual(largestSpanishScalePrompt.split(separator: " ").count, 25)
    let largestFrenchScalePrompt = StarterLexicon.prompt(
      wordCount: 25, language: .french600k, contentOptions: ContentOptions())
    XCTAssertGreaterThanOrEqual(largestFrenchScalePrompt.split(separator: " ").count, 25)
    let largestGermanScalePrompt = StarterLexicon.prompt(
      wordCount: 25, language: .german250k, contentOptions: ContentOptions())
    XCTAssertEqual(largestGermanScalePrompt.split(separator: " ").count, 25)
    let largestRomanianScalePrompt = StarterLexicon.prompt(
      wordCount: 25, language: .romanian200k, contentOptions: ContentOptions())
    XCTAssertEqual(largestRomanianScalePrompt.split(separator: " ").count, 25)
    let largestPolishScalePrompt = StarterLexicon.prompt(
      wordCount: 25, language: .polish200k, contentOptions: ContentOptions())
    XCTAssertEqual(largestPolishScalePrompt.split(separator: " ").count, 25)
    let largestBelarusianScalePrompt = StarterLexicon.prompt(
      wordCount: 25, language: .belarusian100k, contentOptions: ContentOptions())
    XCTAssertEqual(largestBelarusianScalePrompt.split(separator: " ").count, 25)
    let largestRussianScalePrompt = StarterLexicon.prompt(
      wordCount: 25, language: .russian375k, contentOptions: ContentOptions())
    XCTAssertGreaterThanOrEqual(largestRussianScalePrompt.split(separator: " ").count, 25)
    let largestPortugueseScalePrompt = StarterLexicon.prompt(
