  func testResultCSVExportEscapesLocalMetadataAndUsesUtcFilename() throws {
    let configuration = TestConfiguration.timed(
      seconds: 30, difficulty: .expert, language: .french,
      contentOptions: .init(includePunctuation: true, includeNumbers: true)
    )
    .with(modifiers: [.uppercase, .rot13])
    let result = CompletedTestResult(
      id: try XCTUnwrap(UUID(uuidString: "00000000-0000-0000-0000-000000000007")),
      configuration: configuration, outcome: .completed,
      startedAt: Date(timeIntervalSince1970: 0),
      finishedAt: Date(timeIntervalSince1970: 2.5), afkDuration: 0.5,
      typedCharacterCount: 12, correctCharacterCount: 11, errorCount: 1, wpm: 60, rawWpm: 66,
      accuracy: 92, restartCount: 3,
      characterStats: .init(matched: 9, incorrect: 1, extra: 2, missed: 3),
      keyDurationSamples: [0.08, 0.12],
      keySpacingSamples: [0.1, 0.2], keyOverlapDuration: 0.03,
      tags: ["focus, \"deep\"", "café"], prompt: "private prompt",
      replayEvents: [.init(offset: 0.5, kind: .insert, text: "bonjour")]
    )

    let csv = ResultCSVExport.csvString(for: [result])
    XCTAssertTrue(csv.hasPrefix(ResultCSVExport.columns.joined(separator: ",") + "\r\n"))
    XCTAssertTrue(ResultCSVExport.columns.contains("restart_count"))
    XCTAssertTrue(csv.contains("00000000-0000-0000-0000-000000000007,completed,60,66,92,"))
    XCTAssertTrue(
      csv.contains(",11,12,1,9,1,2,3,100.00,20.00,2,150.00,50.00,2,30.00,time,"))
    XCTAssertTrue(csv.contains(",true,true,expert,uppercase;rot13,\"focus, \"\"deep\"\";café\","))
    XCTAssertTrue(csv.contains("1970-01-01T00:00:00"))
    XCTAssertTrue(csv.hasSuffix("2.50,0.50,2.00,3\r\n"))
    XCTAssertFalse(csv.contains("private prompt"))
    XCTAssertTrue(csv.hasSuffix("\r\n"))
    XCTAssertEqual(ResultCSVExport.csvString(for: []), ResultCSVExport.columns.joined(separator: ",") + "\r\n")
    XCTAssertEqual(
      ResultCSVExport.filename(for: Date(timeIntervalSince1970: 0)),
      "typebar-results-19700101-000000.csv")
  }

  func testRemoteResultCSVExportLoadsEveryStablePageAndRejectsAChangingSnapshot() async throws {
    let payload = #"""
      [
        {"id":"00000000-0000-0000-0000-000000000001","mode":"time","language":"english","durationSeconds":30,"wordLimit":null,"wpm":61,"rawWpm":66,"accuracy":97,"consistency":88.5,"errorCount":2,"eventCount":140,"tags":["focus, \"steady\""],"startedAt":"1970-01-01T00:00:00Z","finishedAt":"1970-01-01T00:00:30Z"},
        {"id":"00000000-0000-0000-0000-000000000002","mode":"words","language":"french","durationSeconds":null,"wordLimit":25,"wpm":54,"rawWpm":58,"accuracy":95,"consistency":80,"errorCount":3,"eventCount":125,"tags":[],"startedAt":"1970-01-02T00:00:00Z","finishedAt":"1970-01-02T00:00:40Z"},
        {"id":"00000000-0000-0000-0000-000000000003","mode":"quote","language":"german","durationSeconds":null,"wordLimit":null,"wpm":49,"rawWpm":52,"accuracy":94,"consistency":76.25,"errorCount":4,"eventCount":180,"tags":["café"],"startedAt":"1970-01-03T00:00:00Z","finishedAt":"1970-01-03T00:01:00Z"}
      ]
      """#
    let decoder = JSONDecoder()
    decoder.dateDecodingStrategy = .iso8601
    let results = try decoder.decode([RemoteAccountResult].self, from: Data(payload.utf8))
    var requests: [(offset: Int, limit: Int)] = []

    let loaded = try await RemoteResultCSVExport.loadAll(pageSize: 2) { offset, limit in
      requests.append((offset, limit))
      return RemoteAccountResultPage(
        results: Array(results.dropFirst(offset).prefix(limit)), total: results.count)
    }

    XCTAssertEqual(requests.map(\.offset), [0, 2])
    XCTAssertEqual(requests.map(\.limit), [2, 2])
    XCTAssertEqual(loaded.map(\.id), results.map(\.id))
    let csv = RemoteResultCSVExport.csvString(for: loaded)
    XCTAssertTrue(csv.hasPrefix(RemoteResultCSVExport.columns.joined(separator: ",") + "\r\n"))
    XCTAssertTrue(csv.contains("00000000-0000-0000-0000-000000000001,time,30,,english,61,66,97,88.50,2,140"))
    XCTAssertTrue(csv.contains("\"focus, \"\"steady\"\"\""))
    XCTAssertFalse(csv.localizedCaseInsensitiveContains("prompt"))
    XCTAssertFalse(csv.localizedCaseInsensitiveContains("replay"))
    XCTAssertEqual(
      RemoteResultCSVExport.filename(for: Date(timeIntervalSince1970: 0)),
      "typebar-server-results-19700101-000000.csv")

    do {
      _ = try await RemoteResultCSVExport.loadAll(pageSize: 2) { offset, _ in
        offset == 0
          ? RemoteAccountResultPage(results: Array(results.prefix(2)), total: 3)
          : RemoteAccountResultPage(results: [results[2]], total: 4)
      }
      XCTFail("A changing server result set must not produce a partial export")
    } catch let error as RemoteResultCSVExportError {
      XCTAssertEqual(error, .changedDuringExport)
    }

    do {
      _ = try await RemoteResultCSVExport.loadAll(pageSize: 2) { offset, _ in
        offset == 0
          ? RemoteAccountResultPage(results: Array(results.prefix(2)), total: 3)
          : RemoteAccountResultPage(results: [results[1]], total: 3)
      }
      XCTFail("A duplicate page must not produce a partial export")
    } catch let error as RemoteResultCSVExportError {
      XCTAssertEqual(error, .changedDuringExport)
    }
  }

  func testSlowWordPracticeUsesReferenceTwentyPercentSelectionAndWeightsTheSlowest() throws {
    let reviews = [
      TypedWordReview(index: 0, target: "ember", typed: "ember"),
      TypedWordReview(index: 1, target: "cabin", typed: "cabin"),
      TypedWordReview(index: 2, target: "planet", typed: "planet"),
      TypedWordReview(index: 3, target: "willow", typed: "willow"),
      TypedWordReview(index: 4, target: "stream", typed: "stream"),
      TypedWordReview(index: 5, target: "ignored", typed: "ignored"),
    ]
    let shortPlan = try XCTUnwrap(
      SlowWordPracticePlan.make(reviews: Array(reviews.prefix(4)), bursts: [80, 70, 60, 50]))
    XCTAssertEqual(shortPlan.selectedWords, ["planet"])

    let plan = try XCTUnwrap(
      SlowWordPracticePlan.make(reviews: reviews, bursts: [90, 40, 25, 55, 70, nil]))
    XCTAssertEqual(plan.selectedWords, ["planet"])
    XCTAssertEqual(plan.exerciseWords, ["planet"])

    let repeatedTarget = try XCTUnwrap(
      SlowWordPracticePlan.make(
        reviews: [
          TypedWordReview(index: 0, target: "cabin", typed: "cabin"),
          TypedWordReview(index: 1, target: "cabin", typed: "cabin"),
          TypedWordReview(index: 2, target: "planet", typed: "planet"),
          TypedWordReview(index: 3, target: "willow", typed: "willow"),
          TypedWordReview(index: 4, target: "stream", typed: "stream"),
          TypedWordReview(index: 5, target: "ember", typed: "ember"),
        ],
        bursts: [10, 20, 30, 40, 50, 60]))
    XCTAssertEqual(repeatedTarget.selectedWords, ["cabin"])
  }

  func testSlowWordCopyUsesAverageThresholdAndPreservesTypedOrder() {
    let reviews = [
      TypedWordReview(index: 0, target: "ember", typed: "ember"),
      TypedWordReview(index: 1, target: "cabin", typed: "cabin"),
      TypedWordReview(index: 2, target: "ember", typed: "ember"),
      TypedWordReview(index: 3, target: "tail", typed: "tail"),
    ]
    let bursts: [Int?] = [40, 101, nil, 0]

    XCTAssertEqual(SlowWordCopyPolicy.defaultThreshold(bursts: bursts), 71)
    XCTAssertEqual(
      SlowWordCopyPolicy.words(reviews: reviews, bursts: bursts, below: 80),
      ["ember", "tail"])
    XCTAssertEqual(
      SlowWordCopyPolicy.words(reviews: reviews, bursts: bursts, below: 40),
      ["tail"])
    XCTAssertEqual(
      SlowWordCopyPolicy.words(
        reviews: reviews, bursts: [40, 101, 50, nil], below: 80),
      ["ember", "ember"])
    XCTAssertTrue(SlowWordCopyPolicy.words(reviews: reviews, bursts: bursts, below: 0).isEmpty)
    XCTAssertEqual(SlowWordCopyPolicy.defaultThreshold(bursts: [nil, 0]), 80)
  }

  func testContextualMissedWordPracticeKeepsOnlyAttemptedTargetContext() throws {
