  @MainActor
  func testNativeInputBridgeSendsArrowKeysToTheTypingEngineOnlyInArrowMode() throws {
    var accepted = [String]()
    let view = TypingInputView()
    view.onInsert = { text, _ in accepted.append(text) }
    let up = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [], timestamp: 0, windowNumber: 0,
        context: nil, characters: "", charactersIgnoringModifiers: "", isARepeat: false,
        keyCode: 126))

    view.mapsArrowKeysToInput = true
    view.keyDown(with: up)
    XCTAssertEqual(accepted, ["↑"])

    accepted.removeAll()
    view.mapsArrowKeysToInput = false
    view.keyDown(with: up)
    XCTAssertTrue(accepted.isEmpty)
  }

  @MainActor
  func testNativeInputBridgeReportsPhysicalKeyDownRepeatAndKeyUp() throws {
    var events = [String]()
    let view = TypingInputView()
    view.onPhysicalKey = { keyCode, isKeyDown, isRepeat in
      events.append("\(keyCode):\(isKeyDown):\(isRepeat)")
    }
    let keyDown = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [], timestamp: 0, windowNumber: 0,
        context: nil, characters: "a", charactersIgnoringModifiers: "a", isARepeat: false,
        keyCode: 0))
    let repeatKeyDown = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [], timestamp: 0.1, windowNumber: 0,
        context: nil, characters: "a", charactersIgnoringModifiers: "a", isARepeat: true,
        keyCode: 0))
    let keyUp = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyUp, location: .zero, modifierFlags: [], timestamp: 0.2, windowNumber: 0,
        context: nil, characters: "a", charactersIgnoringModifiers: "a", isARepeat: false,
        keyCode: 0))

    view.keyDown(with: keyDown)
    view.keyDown(with: repeatKeyDown)
    view.keyUp(with: keyUp)

    XCTAssertEqual(events, ["0:true:false", "0:true:true", "0:false:false"])
  }

  @MainActor
  func testNativeInputBridgeOpensCommandPaletteWithCommandShiftPWithoutTyping() throws {
    var opens = 0
    var accepted = [String]()
    var physicalEvents = 0
    let view = TypingInputView()
    view.onOpenCommandPalette = { opens += 1 }
    view.onInsert = { text, _ in accepted.append(text) }
    view.onPhysicalKey = { _, _, _ in physicalEvents += 1 }
    let shortcut = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [.command, .shift], timestamp: 0,
        windowNumber: 0, context: nil, characters: "P", charactersIgnoringModifiers: "p",
        isARepeat: false, keyCode: 35))
    let repeatedShortcut = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [.command, .shift], timestamp: 0.1,
        windowNumber: 0, context: nil, characters: "P", charactersIgnoringModifiers: "p",
        isARepeat: true, keyCode: 35))
    let shortcutRelease = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyUp, location: .zero, modifierFlags: [.command, .shift], timestamp: 0.2,
        windowNumber: 0, context: nil, characters: "P", charactersIgnoringModifiers: "p",
        isARepeat: false, keyCode: 35))

    view.keyDown(with: shortcut)
    view.keyDown(with: repeatedShortcut)
    view.keyUp(with: shortcutRelease)

    XCTAssertEqual(opens, 1)
    XCTAssertTrue(accepted.isEmpty)
    XCTAssertEqual(physicalEvents, 0)
  }

  @MainActor
  func testNativeInputBridgeUsesDynamicEscapeAndProtectedTabPaletteShortcuts() throws {
    let escape = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [], timestamp: 0, windowNumber: 0,
        context: nil, characters: "\u{1B}", charactersIgnoringModifiers: "\u{1B}",
        isARepeat: false, keyCode: 53))
    let tab = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [], timestamp: 0, windowNumber: 0,
        context: nil, characters: "\t", charactersIgnoringModifiers: "\t",
        isARepeat: false, keyCode: 48))
    let shiftTab = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [.shift], timestamp: 0,
        windowNumber: 0, context: nil, characters: "\t", charactersIgnoringModifiers: "\t",
        isARepeat: false, keyCode: 48))

    var escapeOpens = 0
    var escapePhysicalEvents = 0
    let escapeView = TypingInputView()
    escapeView.onOpenCommandPalette = { escapeOpens += 1 }
    escapeView.onPhysicalKey = { _, _, _ in escapePhysicalEvents += 1 }
    escapeView.keyDown(with: escape)
    XCTAssertEqual(escapeOpens, 1)
    XCTAssertEqual(escapePhysicalEvents, 0)

    var tabOpens = 0
    var tabPhysicalEvents = 0
    let tabView = TypingInputView()
    tabView.quickRestartKey = .escape
    tabView.onOpenCommandPalette = { tabOpens += 1 }
    tabView.onPhysicalKey = { _, _, _ in tabPhysicalEvents += 1 }
    tabView.keyDown(with: tab)
    XCTAssertEqual(tabOpens, 1)
    XCTAssertEqual(tabPhysicalEvents, 0)

    var protectedTabOpens = 0
    var protectedTabInput = [String]()
    let protectedTabView = TypingInputView()
    protectedTabView.quickRestartKey = .escape
    protectedTabView.acceptsTabInput = true
    protectedTabView.onOpenCommandPalette = { protectedTabOpens += 1 }
    protectedTabView.onInsert = { text, _ in protectedTabInput.append(text) }
    protectedTabView.keyDown(with: tab)
    protectedTabView.keyDown(with: shiftTab)
    XCTAssertEqual(protectedTabInput, ["\t"])
    XCTAssertEqual(protectedTabOpens, 1)
  }

  @MainActor
  func testNativeInputBridgeOnlySendsReturnWhenThePromptAcceptsNewlines() throws {
    var accepted = [String]()
    var restarts = 0
    let view = TypingInputView()
    view.onInsert = { text, _ in accepted.append(text) }
    view.onRestart = { restarts += 1 }
    let enter = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [], timestamp: 0, windowNumber: 0,
        context: nil, characters: "\r", charactersIgnoringModifiers: "\r", isARepeat: false,
        keyCode: 36))

    view.quickRestartKey = .enter
    view.acceptsNewlineInput = true
    view.keyDown(with: enter)
    XCTAssertEqual(accepted, ["\n"])

    accepted.removeAll()
    view.acceptsNewlineInput = false
    view.keyDown(with: enter)
    XCTAssertTrue(accepted.isEmpty)
    XCTAssertEqual(restarts, 1)

    let shiftEnterRestart = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [.shift], timestamp: 0, windowNumber: 0,
        context: nil, characters: "\r", charactersIgnoringModifiers: "\r", isARepeat: false,
        keyCode: 36))
    view.acceptsNewlineInput = true
    view.keyDown(with: shiftEnterRestart)
    XCTAssertEqual(restarts, 2)
    XCTAssertTrue(accepted.isEmpty)

    let shiftEnter = try XCTUnwrap(
      NSEvent.keyEvent(
        with: .keyDown, location: .zero, modifierFlags: [.shift], timestamp: 0, windowNumber: 0,
        context: nil, characters: "\r", charactersIgnoringModifiers: "\r", isARepeat: false,
        keyCode: 36))
    var zenFinishes = 0
    view.acceptsNewlineInput = true
    view.finishesOnShiftEnter = true
    view.onFinishZen = { zenFinishes += 1 }
    view.keyDown(with: shiftEnter)
    XCTAssertEqual(zenFinishes, 1)
    XCTAssertTrue(accepted.isEmpty)
  }

