      (.czech, StarterLexicon.czechWords),
      (.slovak, StarterLexicon.slovakWords),
      (.slovenian, StarterLexicon.slovenianWords),
      (.croatian, StarterLexicon.croatianWords),
      (.serbian, StarterLexicon.serbianWords),
      (.serbianLatin, StarterLexicon.serbianLatinWords),
      (.bulgarian, StarterLexicon.bulgarianWords),
      (.bulgarianLatin, StarterLexicon.bulgarianLatinWords),
      (.romanian, StarterLexicon.romanianWords),
      (.finnish, StarterLexicon.finnishWords),
      (.estonian, StarterLexicon.estonianWords),
      (.icelandic, StarterLexicon.icelandicWords),
      (TypingLanguage.french, StarterLexicon.frenchWords), (.italian, StarterLexicon.italianWords),
      (.portuguese, StarterLexicon.portugueseWords),
      (.portugueseAccents, StarterLexicon.portugueseAccentsWords),
      (.russian, StarterLexicon.russianWords),
      (.russianAbbreviations, StarterLexicon.russianAbbreviationWords),
      (.ukrainian, StarterLexicon.ukrainianWords),
      (.ukrainianEndings, StarterLexicon.ukrainianEndingWords),
      (.ukrainianLatin, StarterLexicon.ukrainianLatinWords),
      (.ukrainianLatynkaEndings, StarterLexicon.ukrainianLatynkaEndingWords),
      (.japaneseRomaji, StarterLexicon.japaneseRomajiWords),
      (.korean, StarterLexicon.koreanWords), (.turkish, StarterLexicon.turkishWords),
      (.polish, StarterLexicon.polishWords),
    ] {
      let prompt = OfflineContent.generatedPrompt(
        wordCount: 12, language: language,
        contentOptions: .init(includePunctuation: true, includeNumbers: true))
      let invalidTokens = prompt.split(separator: " ").compactMap { token -> String? in
        if token.allSatisfy(\.isNumber) { return nil }
        let punctuation = language == .tibetan
          ? CharacterSet(charactersIn: "།")
          : language == .banglaLetters
            ? CharacterSet.punctuationCharacters.subtracting(CharacterSet(charactersIn: "।"))
          : language == .git
            ? CharacterSet.punctuationCharacters.subtracting(CharacterSet(charactersIn: "@-"))
          : language == .klingon
            ? CharacterSet.punctuationCharacters.subtracting(CharacterSet(charactersIn: "'"))
            : language == .lojbanCmavo
              ? CharacterSet.punctuationCharacters.subtracting(CharacterSet(charactersIn: ".'"))
              : CharacterSet.punctuationCharacters
        let normalized = token.trimmingCharacters(
          in: punctuation)
        return lexicon.contains(normalized) ? nil : "\(token) → \(normalized)"
      }
      XCTAssertTrue(
        invalidTokens.isEmpty,
        "\(language.rawValue): \(prompt); invalid: \(invalidTokens.joined(separator: ", "))")
      XCTAssertEqual(OfflineContent.quotes(for: language, length: .short).count, 1)
      XCTAssertEqual(OfflineContent.quotes(for: language, length: .medium).count, 1)
      XCTAssertEqual(OfflineContent.quotes(for: language, length: .long).count, 1)
