  func testLazyLatinModifierNormalizesAccentsLigaturesAndGeneratedPrompts() {
    XCTAssertEqual(TestModifier.inputPreferenceCases, [.lazyLatin])
    XCTAssertFalse(TestModifier.funboxPreferenceCases.contains(.lazyLatin))
    XCTAssertEqual(
      Set(TestModifier.inputPreferenceCases + TestModifier.funboxPreferenceCases),
      Set(TestModifier.allCases))
    XCTAssertEqual(
      SettingsSearch.preferenceCatalog.first(where: { $0.id == "lazyMode" })?.section,
      .test)
    XCTAssertEqual(TypingTextNormalizer.lazyLatin("árvore Straße cœur Łódź"), "arvore Strasse coeur Lodz")
    XCTAssertEqual(
      TypingTextNormalizer.lazyLatin("أَإِآ كِتابٌ مُدَرِّسْ"), "ااا كتاب مدرس")
    XCTAssertEqual(
      ArabicLazyInputPolicy.effectiveModifiers([], language: .arabic, automaticallyEnabled: true),
      [.lazyLatin])
    XCTAssertEqual(
      ArabicLazyInputPolicy.effectiveModifiers([], language: .arabic, automaticallyEnabled: false),
      [])
    XCTAssertEqual(
      ArabicLazyInputPolicy.effectiveModifiers([], language: .arabicEgypt, automaticallyEnabled: true),
      [])
    XCTAssertEqual(
      ArabicLazyInputPolicy.effectiveModifiers([.lazyLatin], language: .arabicEgypt, automaticallyEnabled: true),
      [.lazyLatin])
    XCTAssertEqual(
      ArabicLazyInputPolicy.effectiveModifiers([], language: .arabicMorocco, automaticallyEnabled: true),
      [])
    XCTAssertEqual(
      ArabicLazyInputPolicy.effectiveModifiers([.lazyLatin], language: .arabicMorocco, automaticallyEnabled: true),
      [.lazyLatin])
    XCTAssertEqual(
      ArabicLazyInputPolicy.effectiveModifiers([.lazyLatin], language: .pashto, automaticallyEnabled: true),
      [])
    XCTAssertEqual(
