  func testWeakSpotPracticeUsesOnlyTypebarWordsAndCompletedLocalReplayErrors() {
    let result = CompletedTestResult(
      id: UUID(), configuration: .words(2, language: .english), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(10), typedCharacterCount: 12,
      correctCharacterCount: 11, errorCount: 1, wpm: 14, rawWpm: 14, accuracy: 92,
      prompt: "amber harbor", replayEvents: [.init(offset: 1, kind: .insert, text: "axber harbor")]
    )
    let prompt = try? XCTUnwrap(
      WeakSpotPractice.prompt(
        results: [result], language: .english, englishVariant: .american, wordCount: 6))
    XCTAssertNotNil(prompt)
    XCTAssertEqual(WeakSpotPractice.characterScores(results: [result], language: .english)["m"], 1)
    XCTAssertTrue(
      prompt?.split(separator: " ").allSatisfy { StarterLexicon.words.contains(String($0)) }
        ?? false)
    XCTAssertTrue(prompt?.contains("amber") ?? false)

    let ukrainianResult = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .ukrainian), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(5), typedCharacterCount: 5,
      correctCharacterCount: 4, errorCount: 1, wpm: 12, rawWpm: 12, accuracy: 80,
      prompt: "ґрунт", replayEvents: [.init(offset: 1, kind: .insert, text: "грунт")])
    XCTAssertEqual(
      WeakSpotPractice.prompt(
        results: [ukrainianResult], language: .ukrainian, englishVariant: .american, wordCount: 1),
      "ґрунт")
    let ukrainianLatinResult = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .ukrainianLatin), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(5), typedCharacterCount: 5,
      correctCharacterCount: 4, errorCount: 1, wpm: 12, rawWpm: 12, accuracy: 80,
      prompt: "grunt", replayEvents: [.init(offset: 1, kind: .insert, text: "krunt")])
    XCTAssertEqual(
      WeakSpotPractice.prompt(
        results: [ukrainianLatinResult], language: .ukrainianLatin, englishVariant: .american,
        wordCount: 1),
      "grunt")
    let dutchResult = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .dutch), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(5), typedCharacterCount: 3,
      correctCharacterCount: 2, errorCount: 1, wpm: 12, rawWpm: 12, accuracy: 67,
      prompt: "één", replayEvents: [.init(offset: 1, kind: .insert, text: "een")])
    XCTAssertEqual(
      WeakSpotPractice.prompt(
        results: [dutchResult], language: .dutch, englishVariant: .american, wordCount: 1),
      "één")
    let danishResult = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .danish), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(5), typedCharacterCount: 2,
      correctCharacterCount: 1, errorCount: 1, wpm: 12, rawWpm: 12, accuracy: 50,
      prompt: "én", replayEvents: [.init(offset: 1, kind: .insert, text: "en")])
    XCTAssertEqual(
      WeakSpotPractice.prompt(
        results: [danishResult], language: .danish, englishVariant: .american, wordCount: 1),
      "én")
    let norwegianBokmalResult = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .norwegianBokmal), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(5), typedCharacterCount: 3,
      correctCharacterCount: 2, errorCount: 1, wpm: 12, rawWpm: 12, accuracy: 67,
      prompt: "vær", replayEvents: [.init(offset: 1, kind: .insert, text: "var")])
    XCTAssertEqual(
      WeakSpotPractice.prompt(
        results: [norwegianBokmalResult], language: .norwegianBokmal, englishVariant: .american,
        wordCount: 1),
      "vær")
    let swedishResult = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .swedish), outcome: .completed,
