  func testWeakSpotReportAggregatesSavedReplayAndBuildsDeterministicPractice() throws {
    let repeatedErrors = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .english), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(5), typedCharacterCount: 3,
      correctCharacterCount: 0, errorCount: 3, wpm: 0, rawWpm: 7, accuracy: 0,
      prompt: "amber",
      replayEvents: [
        .init(offset: 1, kind: .insert, text: "x"),
        .init(offset: 2, kind: .delete, text: ""),
        .init(offset: 3, kind: .insert, text: "yx"),
      ])
    let cleanReplay = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .english), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(5), typedCharacterCount: 5,
      correctCharacterCount: 5, errorCount: 0, wpm: 12, rawWpm: 12, accuracy: 100,
      prompt: "amber", replayEvents: [.init(offset: 1, kind: .insert, text: "amber")])
    let otherLanguage = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .spanish), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(5), typedCharacterCount: 3,
      correctCharacterCount: 2, errorCount: 1, wpm: 12, rawWpm: 12, accuracy: 67,
      prompt: "mar", replayEvents: [.init(offset: 1, kind: .insert, text: "xar")])
    let abandoned = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .english), outcome: .abandoned,
      startedAt: start, finishedAt: start.addingTimeInterval(2), typedCharacterCount: 1,
      correctCharacterCount: 0, errorCount: 1, wpm: 0, rawWpm: 6, accuracy: 0,
      prompt: "amber", replayEvents: [.init(offset: 1, kind: .insert, text: "x")])

    let results = [repeatedErrors, cleanReplay, otherLanguage, abandoned]
    let report = try XCTUnwrap(
      WeakSpotPractice.report(
        results: results, language: .english, englishVariant: .american, suggestionLimit: 3))

    XCTAssertEqual(report.language, .english)
    XCTAssertEqual(report.analyzedResultCount, 2)
    XCTAssertEqual(report.totalMistakeCount, 3)
    XCTAssertEqual(report.characters.map(\.character), ["a", "m"])
    XCTAssertEqual(report.characters.map(\.mistakeCount), [2, 1])
    XCTAssertEqual(report.characters.map(\.attemptCount), [3, 2])
    XCTAssertEqual(report.characters.map(\.averageIntervalMilliseconds), [1_000, nil])
    XCTAssertEqual(report.suggestedWords.count, 3)
    XCTAssertTrue(report.suggestedWords.allSatisfy(StarterLexicon.words.contains))
    XCTAssertTrue(report.suggestedWords[0].contains("a"))

    let prompt = try XCTUnwrap(
      WeakSpotPractice.prompt(
        results: results, language: .english, englishVariant: .american, wordCount: 10))
    XCTAssertEqual(prompt.split(separator: " ").count, 10)
    XCTAssertEqual(
      WeakSpotPractice.report(
        results: results, language: .spanish, englishVariant: .american)?.totalMistakeCount,
      1)
  }

  func testWeakSpotReportFindsSlowCorrectCharactersAndIgnoresAutomaticReplay() throws {
    let slowCorrect = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .english), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(2), typedCharacterCount: 5,
      correctCharacterCount: 5, errorCount: 0, wpm: 30, rawWpm: 30, accuracy: 100,
      prompt: "amber",
      replayEvents: [
        .init(offset: 0.1, kind: .insert, text: "a"),
        .init(offset: 0.2, kind: .insert, text: "m"),
        .init(offset: 0.3, kind: .insert, text: "b"),
        .init(offset: 1.3, kind: .insert, text: "e"),
        .init(offset: 1.4, kind: .insert, text: "r"),
      ])
    let forcedError = CompletedTestResult(
      id: UUID(), configuration: .words(1, language: .english), outcome: .completed,
      startedAt: start, finishedAt: start.addingTimeInterval(1), typedCharacterCount: 2,
      correctCharacterCount: 1, errorCount: 1, wpm: 24, rawWpm: 24, accuracy: 50,
      prompt: "am",
      replayEvents: [
        .init(offset: 0.1, kind: .insert, text: "x", automatic: true),
        .init(offset: 0.2, kind: .insert, text: "a", forceError: true),
        .init(offset: 0.3, kind: .insert, text: "m"),
      ])

    let slowReport = try XCTUnwrap(
      WeakSpotPractice.report(
        results: [slowCorrect], language: .english, englishVariant: .american))
    XCTAssertEqual(slowReport.totalMistakeCount, 0)
    XCTAssertEqual(slowReport.characters.first?.character, "e")
    XCTAssertEqual(slowReport.characters.first?.averageIntervalMilliseconds, 1_000)
    XCTAssertTrue(slowReport.suggestedWords.first?.contains("e") ?? false)

    let forcedReport = try XCTUnwrap(
      WeakSpotPractice.report(
        results: [forcedError], language: .english, englishVariant: .american))
    XCTAssertEqual(forcedReport.totalMistakeCount, 1)
    XCTAssertEqual(WeakSpotPractice.characterScores(results: [forcedError], language: .english), ["a": 1])
    XCTAssertFalse(forcedReport.characters.contains(where: { $0.character == "x" }))
  }

  func testLocalWordFilterUsesOnlyRequestedCharactersLengthsAndRegularExpressions() throws {
    let criteria = LocalWordFilter.Criteria(
      includeCharacters: "a", excludeCharacters: "r", minimumLength: 3, maximumLength: 5,
      regularExpression: "^a", exactCharactersOnly: false)
    XCTAssertEqual(
      try LocalWordFilter.words(in: ["amber", "atlas", "bar", "baker"], matching: criteria).get(),
      ["atlas"])
    let indexed = IndexedLexicon(count: 4) { ["amber", "atlas", "bar", "baker"][$0] }
    XCTAssertEqual(try LocalWordFilter.words(in: indexed, matching: criteria).get(), ["atlas"])

    let exact = LocalWordFilter.Criteria(
      includeCharacters: "a b", excludeCharacters: "ignored", minimumLength: nil,
      maximumLength: nil, regularExpression: "[", exactCharactersOnly: true)
    XCTAssertEqual(
      try LocalWordFilter.words(in: ["aba", "bad", "cab"], matching: exact).get(), ["aba"])

    XCTAssertEqual(
      LocalWordFilter.words(
        in: ["amber"], matching: .init(exactCharactersOnly: true)),
      .failure(.exactCharactersNeedInclude))
    XCTAssertEqual(
      LocalWordFilter.words(
        in: ["amber"], matching: .init(minimumLength: 6, maximumLength: 3)),
      .failure(.invalidLengthRange))
    XCTAssertEqual(
      LocalWordFilter.words(
        in: ["amber"], matching: .init(regularExpression: "[")),
      .failure(.invalidRegularExpression))
  }

