  func testQuoteSelectionModesSeparateLengthsFavoritesAndLockedSearch() {
    let quotes = [
      OfflineQuote(id: "short-favorite", title: "Morning", text: "quiet dawn", language: .english, length: .short),
      OfflineQuote(id: "long-favorite", title: "Harbor", text: "bright harbor", language: .english, length: .long),
      OfflineQuote(id: "long-other", title: "Orchard", text: "quiet orchard", language: .english, length: .long),
    ]
    let favorites = Set(["short-favorite", "long-favorite"])

    XCTAssertEqual(
      QuoteSelection.filtered(
        quotes, mode: .lengths, lengths: [.short], searchQuery: "harbor",
        isFavorite: favorites.contains).map(\.id),
      ["short-favorite"])
    XCTAssertEqual(
      QuoteSelection.filtered(
        quotes, mode: .favorites, lengths: [.short], searchQuery: "orchard",
        isFavorite: favorites.contains).map(\.id),
      ["short-favorite", "long-favorite"])
    XCTAssertEqual(
      QuoteSelection.filtered(
        quotes, mode: .search, lengths: [.short], searchQuery: "quiet orchard",
        isFavorite: favorites.contains).map(\.id),
      ["long-other"])
    XCTAssertTrue(QuoteSelectionMode.lengths.advancesAutomatically)
    XCTAssertTrue(QuoteSelectionMode.favorites.advancesAutomatically)
    XCTAssertFalse(QuoteSelectionMode.search.advancesAutomatically)
    XCTAssertEqual(
      QuoteSelection.resolvedMode(.favorites, hasEligibleQuotes: false), .lengths)
    XCTAssertEqual(
      QuoteSelection.resolvedMode(.search, hasEligibleQuotes: false), .lengths)
    XCTAssertEqual(
      QuoteSelection.resolvedMode(.favorites, hasEligibleQuotes: true), .favorites)
  }

  @MainActor
  func testRemoteAnnouncementCenterPersistsLocalDismissalsButKeepsStickyItems() {
    let suiteName = "TypebarTests.\(UUID().uuidString)"
    let defaults = UserDefaults(suiteName: suiteName)!
    defer { defaults.removePersistentDomain(forName: suiteName) }
    let ordinary = RemoteAnnouncement(
      id: UUID(), message: "A normal update", level: .notice, sticky: false,
      publishedAt: Date(timeIntervalSince1970: 20))
    let sticky = RemoteAnnouncement(
      id: UUID(), message: "A sticky update", level: .warning, sticky: true,
      publishedAt: Date(timeIntervalSince1970: 10))
    let scheduled = RemoteAnnouncement(
      id: UUID(),
      message: "Maintenance begins {date}; date only {dateNoTime}; relative {dateDifference}.",
      level: .notice, sticky: false, scheduledAt: Date(timeIntervalSince1970: 1_735_776_000),
      publishedAt: Date(timeIntervalSince1970: 30))
    let rendered = scheduled.renderedMessage(
      at: Date(timeIntervalSince1970: 1_735_689_600), locale: Locale(identifier: "en_US_POSIX"),
      timeZone: TimeZone(secondsFromGMT: 0)!)
    XCTAssertFalse(rendered.contains("{date}"))
    XCTAssertFalse(rendered.contains("{dateNoTime}"))
    XCTAssertFalse(rendered.contains("{dateDifference}"))
    XCTAssertTrue(rendered.contains("2025"))
    var legacyPayload = try! JSONSerialization.jsonObject(with: JSONEncoder().encode(ordinary)) as! [String: Any]
    legacyPayload.removeValue(forKey: "scheduledAt")
    let legacyAnnouncement = try! JSONDecoder().decode(
      RemoteAnnouncement.self, from: JSONSerialization.data(withJSONObject: legacyPayload))
    XCTAssertNil(legacyAnnouncement.scheduledAt)
    let center = RemoteAnnouncementCenter(defaults: defaults)
    center.replace(with: [sticky, ordinary])
    XCTAssertEqual(center.visibleAnnouncements.map(\.id), [ordinary.id, sticky.id])

    center.dismiss(ordinary)
    center.dismiss(sticky)
    XCTAssertEqual(center.visibleAnnouncements.map(\.id), [sticky.id])

    let restored = RemoteAnnouncementCenter(defaults: defaults)
    restored.replace(with: [ordinary, sticky])
    XCTAssertEqual(restored.visibleAnnouncements.map(\.id), [sticky.id])
    restored.replace(with: [])
    restored.replace(with: [ordinary])
    XCTAssertEqual(restored.visibleAnnouncements.map(\.id), [ordinary.id])
  }

