    let legacy = try JSONDecoder().decode(
      ResultHistoryFilter.self, from: Data(#"{"tag":"review"}"#.utf8))
    XCTAssertNil(legacy.tagFilter)
    XCTAssertEqual(
      legacy.matchingIDs(entries: entries, personalBestIDs: []), [review.id, both.id])
  }

