  func testLocalPersonalBestTableKeepsTheBestComparableTimeAndWordResults() {
    func result(
      id: UUID = UUID(), configuration: TestConfiguration, wpm: Int, finishedAt: Date,
      outcome: TestOutcome = .completed
    ) -> CompletedTestResult {
      .init(
        id: id, configuration: configuration, outcome: outcome, startedAt: start,
        finishedAt: finishedAt, typedCharacterCount: 100, correctCharacterCount: 100,
        errorCount: 0, wpm: wpm, rawWpm: wpm + 3, accuracy: 98)
    }

    let englishTime = TestConfiguration.timed(seconds: 30, language: .english)
    let olderEnglishTimeID = UUID()
    let lazyEnglishTime = englishTime.with(modifiers: [.lazyLatin])
    let rows = LocalPersonalBestTablePolicy.rows(results: [
      result(
        configuration: englishTime, wpm: 71, finishedAt: start.addingTimeInterval(20)),
      result(
        id: olderEnglishTimeID, configuration: englishTime, wpm: 82,
        finishedAt: start.addingTimeInterval(2)),
      result(
        configuration: englishTime, wpm: 82, finishedAt: start.addingTimeInterval(9)),
      result(
        configuration: .timed(seconds: 30, language: .spanish), wpm: 91,
        finishedAt: start.addingTimeInterval(3)),
      result(
        configuration: lazyEnglishTime, wpm: 76, finishedAt: start.addingTimeInterval(4)),
      result(
        configuration: .words(25, language: .english), wpm: 104,
        finishedAt: start.addingTimeInterval(5)),
      result(
        configuration: englishTime.with(modifiers: [.zipf]), wpm: 999,
        finishedAt: start.addingTimeInterval(6)),
      result(
        configuration: englishTime, wpm: 500, finishedAt: start.addingTimeInterval(7),
        outcome: .abandoned),
      result(
        configuration: .init(
          mode: .quote, duration: nil, wordLimit: nil, difficulty: .normal, rules: .init(),
          language: .english), wpm: 700, finishedAt: start.addingTimeInterval(8)),
    ])

    XCTAssertEqual(rows.map(\.mode), [.time, .time, .time, .words])
    XCTAssertEqual(rows.map(\.wpm), [91, 82, 76, 104])
    XCTAssertEqual(rows.first { $0.language == .english && !$0.usesLazyLatin }?.id, olderEnglishTimeID)
    XCTAssertTrue(rows.first { $0.usesLazyLatin }?.optionsLabel.contains("简化重音") == true)
    XCTAssertEqual(rows.last?.parameterLabel, "25 词")
  }

  func testArchiveRoundTripsIndependentLocalData() throws {
    let settings = AppSettingsSnapshot(fontSize: 32)
    let result = CompletedTestResult(
      id: UUID(), configuration: .timed(seconds: 30), outcome: .completed, startedAt: start,
      finishedAt: start.addingTimeInterval(30), afkDuration: 7, typedCharacterCount: 50,
      correctCharacterCount: 48, errorCount: 2, wpm: 19, rawWpm: 20, accuracy: 96,
      restartCount: 3)
    let preset = NamedPreset(
      name: "Short", definition: .init(configuration: .words(10), quoteID: nil, customText: nil))
    let savedTexts = [
      NamedSavedText(title: "Notes", text: "An original text for focused practice."),
      NamedSavedText(title: "Chapter", text: "amber harbor willow", longProgress: 6),
    ]
    let data = try TypebarDataTransfer.exportArchive(
      settings: settings, results: [result], presets: [preset], savedTexts: savedTexts, at: start)
    let archive = try TypebarDataTransfer.importArchive(from: data)
    XCTAssertEqual(archive.version, 3)
    XCTAssertEqual(archive.settings, settings)
    XCTAssertEqual(archive.results, [result])
    XCTAssertEqual(archive.presets, [preset])
    XCTAssertEqual(archive.savedTexts, savedTexts)

    var versionTwoPayload = try XCTUnwrap(
      JSONSerialization.jsonObject(with: data) as? [String: Any])
    versionTwoPayload["version"] = 2
    var versionTwoResults = try XCTUnwrap(versionTwoPayload["results"] as? [[String: Any]])
    versionTwoResults[0].removeValue(forKey: "restartCount")
    versionTwoPayload["results"] = versionTwoResults
    let versionTwoData = try JSONSerialization.data(withJSONObject: versionTwoPayload)
    let versionTwoArchive = try TypebarDataTransfer.importArchive(from: versionTwoData)
    XCTAssertEqual(versionTwoArchive.version, 2)
    XCTAssertEqual(versionTwoArchive.results.first?.restartCount, 0)

    versionTwoPayload["version"] = 4
    let futureData = try JSONSerialization.data(withJSONObject: versionTwoPayload)
    XCTAssertThrowsError(try TypebarDataTransfer.importArchive(from: futureData)) { error in
      XCTAssertEqual(error as? DataTransferError, .unsupportedVersion(4))
    }
  }

  func testCompletedResultDecodesArchivesWrittenBeforeInactivityTracking() throws {
    let result = CompletedTestResult(
      id: UUID(), configuration: .timed(seconds: 30), outcome: .completed, startedAt: start,
      finishedAt: start.addingTimeInterval(30), afkDuration: 7, typedCharacterCount: 50,
      correctCharacterCount: 48, errorCount: 2, wpm: 19, rawWpm: 20, accuracy: 96)
    let encoded = try JSONEncoder().encode(result)
    var legacyPayload = try XCTUnwrap(JSONSerialization.jsonObject(with: encoded) as? [String: Any])
    legacyPayload.removeValue(forKey: "afkDuration")
    legacyPayload.removeValue(forKey: "restartCount")
    let legacyData = try JSONSerialization.data(withJSONObject: legacyPayload)

    let restored = try JSONDecoder().decode(CompletedTestResult.self, from: legacyData)
    XCTAssertEqual(restored.afkDuration, 0)
    XCTAssertEqual(restored.restartCount, 0)
    XCTAssertEqual(restored.engagedDuration, 30)
    XCTAssertEqual(restored.afkPercentage, 0)

    legacyPayload["restartCount"] = -2
    let invalidRestartData = try JSONSerialization.data(withJSONObject: legacyPayload)
    XCTAssertEqual(
      try JSONDecoder().decode(CompletedTestResult.self, from: invalidRestartData).restartCount, 0)
  }

  func testArchiveMergeSkipsExistingResultsAndPresets() {
    let existingID = UUID()
    let retainedResult = CompletedTestResult(
      id: existingID, configuration: .timed(seconds: 30), outcome: .completed, startedAt: start,
      finishedAt: start.addingTimeInterval(30), typedCharacterCount: 50, correctCharacterCount: 50,
      errorCount: 0, wpm: 20, rawWpm: 20, accuracy: 100)
    let newResult = CompletedTestResult(
      id: UUID(), configuration: .words(10), outcome: .completed, startedAt: start,
      finishedAt: start.addingTimeInterval(20), typedCharacterCount: 50, correctCharacterCount: 49,
      errorCount: 1, wpm: 29, rawWpm: 30, accuracy: 98)
    let existingPreset = NamedPreset(
      name: "Short", definition: .init(configuration: .words(10), quoteID: nil, customText: nil))
    let newPreset = NamedPreset(
      name: "Long",
      definition: .init(configuration: .timed(seconds: 120), quoteID: nil, customText: nil))
    let existingText = NamedSavedText(title: "Existing", text: "Already here")
    let newText = NamedSavedText(title: "New", text: "Bring this one in")
    let archive = TypebarArchive(
      version: 2, exportedAt: start, settings: .init(), results: [retainedResult, newResult],
      presets: [existingPreset, newPreset], savedTexts: [existingText, newText])

    XCTAssertEqual(
      TypebarArchiveMerge.resultsToInsert(from: archive, existingIDs: [existingID]), [newResult])
    XCTAssertEqual(
      TypebarArchiveMerge.presetsToInsert(from: archive, existing: [existingPreset]), [newPreset])
    XCTAssertEqual(
      TypebarArchiveMerge.savedTextsToInsert(from: archive, existing: [existingText]), [newText])
  }

  func testArchiveConflictMergePreservesBothUserAuthoredCopiesAndLocalSettings() throws {
    let sharedThemeID = UUID(uuidString: "00000000-0000-0000-0000-000000000101")!
    let clonedThemeID = UUID(uuidString: "00000000-0000-0000-0000-000000000102")!
    let localTheme = CustomThemeDefinition(
      id: sharedThemeID, name: "Focus", background: .init(red: 0.1, green: 0.1, blue: 0.1),
      panel: .init(red: 0.2, green: 0.2, blue: 0.2),
      accent: .init(red: 0.9, green: 0.6, blue: 0.1), prefersDark: true)
    let remoteTheme = CustomThemeDefinition(
      id: sharedThemeID, name: "Focus", background: .init(red: 0.9, green: 0.9, blue: 0.9),
      panel: .init(red: 0.8, green: 0.8, blue: 0.8),
      accent: .init(red: 0.1, green: 0.4, blue: 0.9), prefersDark: false)
    let localPreset = NamedPreset(
      name: "Daily", definition: .init(configuration: .words(25), quoteID: nil, customText: nil))
    let remotePreset = NamedPreset(
      name: "Daily", definition: .init(configuration: .timed(seconds: 60), quoteID: nil, customText: nil))
    let localText = NamedSavedText(title: "Drill", text: "local words")
    let remoteText = NamedSavedText(title: "Drill", text: "remote words")
    let local = TypebarArchive(
      exportedAt: start,
      settings: .init(
        fontSize: 31, customThemes: [localTheme], activeCustomThemeID: sharedThemeID,
        favoriteThemeIDs: [ThemeFavoritePolicy.customID(for: sharedThemeID)]),
      results: [], presets: [localPreset], savedTexts: [localText])
    let remote = TypebarArchive(
      exportedAt: start.addingTimeInterval(1),
      settings: .init(
        fontSize: 46, customThemes: [remoteTheme], activeCustomThemeID: sharedThemeID,
        favoriteThemeIDs: [ThemeFavoritePolicy.customID(for: sharedThemeID)]),
      results: [], presets: [remotePreset], savedTexts: [remoteText])

    let merged = TypebarArchiveConflictMerge.merge(
      local: local, remote: remote, makeID: { clonedThemeID })

    XCTAssertEqual(merged.settings.fontSize, 31)
    XCTAssertEqual(merged.settings.activeCustomThemeID, sharedThemeID)
    XCTAssertEqual(merged.settings.customThemes.first, localTheme)
    XCTAssertEqual(merged.settings.customThemes.last?.id, clonedThemeID)
    XCTAssertEqual(merged.settings.customThemes.last?.name, "Focus（同步冲突）")
    XCTAssertTrue(
      merged.settings.favoriteThemeIDs.contains(ThemeFavoritePolicy.customID(for: clonedThemeID)))
    XCTAssertEqual(merged.presets.map(\.name), ["Daily", "Daily（同步冲突）"])
    XCTAssertEqual(merged.presets.last?.definition, remotePreset.definition)
    XCTAssertEqual(merged.savedTexts.map(\.title), ["Drill", "Drill（同步冲突）"])
    XCTAssertEqual(merged.savedTexts.last?.text, remoteText.text)
  }

  func testArchiveConflictMergeReportsOnlyRenamedCopies() throws {
    let sharedThemeID = UUID(uuidString: "00000000-0000-0000-0000-000000000111")!
    let clonedThemeID = UUID(uuidString: "00000000-0000-0000-0000-000000000112")!
    let sharedLayoutID = UUID(uuidString: "00000000-0000-0000-0000-000000000113")!
    let clonedLayoutID = UUID(uuidString: "00000000-0000-0000-0000-000000000114")!
    let localTheme = CustomThemeDefinition(
      id: sharedThemeID, name: "Focus", background: .init(red: 0.1, green: 0.1, blue: 0.1),
      panel: .init(red: 0.2, green: 0.2, blue: 0.2),
      accent: .init(red: 0.9, green: 0.6, blue: 0.1), prefersDark: true)
    let remoteTheme = CustomThemeDefinition(
      id: sharedThemeID, name: "Focus", background: .init(red: 0.9, green: 0.9, blue: 0.9),
      panel: .init(red: 0.8, green: 0.8, blue: 0.8),
      accent: .init(red: 0.1, green: 0.4, blue: 0.9), prefersDark: false)
    let localLayout = CustomKeyboardGuideLayout(
      id: sharedLayoutID, name: "Board", numberRow: "123", topRow: "qwe",
      homeRow: "asd", bottomRow: "zxc")
    let remoteLayout = CustomKeyboardGuideLayout(
      id: sharedLayoutID, name: "Board", numberRow: "456", topRow: "rty",
      homeRow: "fgh", bottomRow: "vbn")
    let local = TypebarArchive(
      exportedAt: start,
      settings: .init(customThemes: [localTheme], customKeyboardLayouts: [localLayout]),
      results: [],
      presets: [
        .init(name: "Daily", definition: .init(configuration: .words(25), quoteID: nil, customText: nil))
      ],
      savedTexts: [.init(title: "Drill", text: "local words")])
    let remote = TypebarArchive(
      exportedAt: start,
      settings: .init(customThemes: [remoteTheme], customKeyboardLayouts: [remoteLayout]),
      results: [],
      presets: [
        .init(name: "Daily", definition: .init(configuration: .timed(seconds: 60), quoteID: nil, customText: nil)),
        .init(name: "Unique", definition: .init(configuration: .words(10), quoteID: nil, customText: nil)),
      ],
      savedTexts: [
        .init(title: "Drill", text: "remote words"),
        .init(title: "Unique", text: "new words"),
