  func testDailyActivityGroupsMetricsByCalendarDay() {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(secondsFromGMT: 0)!
    let metrics = [
      ResultMetric(
        finishedAt: Date(timeIntervalSince1970: 86_400 + 60), wpm: 40, accuracy: 90,
        typingSeconds: 30, consistency: 70, restartCount: 2),
      ResultMetric(
        finishedAt: Date(timeIntervalSince1970: 86_400 + 3_600), wpm: 51, accuracy: 81,
        typingSeconds: 45, consistency: 90, restartCount: 1),
      ResultMetric(
        finishedAt: Date(timeIntervalSince1970: 172_800 + 60), wpm: 60, accuracy: 90,
        typingSeconds: 15, consistency: 50),
    ]
    let activity = ActivityAggregation.daily(metrics: metrics, calendar: calendar)
    XCTAssertEqual(activity.map(\.completedTests), [2, 1])
    XCTAssertEqual(activity.map(\.typingSeconds), [75, 15])
    XCTAssertEqual(activity.map(\.averageWPM), [45.5, 60])
    XCTAssertEqual(activity.map(\.highestWPM), [51, 60])
    XCTAssertEqual(activity.map(\.averageAccuracy), [85.5, 90])
    XCTAssertEqual(activity.map(\.averageConsistency), [80, 50])
    XCTAssertEqual(activity.map(\.restartsPerCompletedTest), [1.5, 0])
  }

  func testRecentActivityBarsFillEveryRequestedDayWithoutCollapsingGaps() {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(secondsFromGMT: 0)!
    let end = Date(timeIntervalSince1970: 345_600)
    let activity = [
      DailyActivity(
        day: end.addingTimeInterval(-172_800), completedTests: 2, typingSeconds: 75,
        averageWPM: 45.5, highestWPM: 51, averageAccuracy: 85.5, averageConsistency: 80,
        restartsPerCompletedTest: 1.5),
      DailyActivity(
        day: end, completedTests: 1, typingSeconds: 30, averageWPM: 60, highestWPM: 60,
        averageAccuracy: 90, averageConsistency: 50, restartsPerCompletedTest: 0),
    ]

    let points = ActivityAggregation.recentDays(
      activity: activity, days: 4, endingAt: end, calendar: calendar)

    XCTAssertEqual(points.map(\.completedTests), [0, 2, 0, 1])
    XCTAssertEqual(points.map(\.typingSeconds), [0, 75, 0, 30])
    XCTAssertEqual(points.map(\.averageWPM), [0, 45.5, 0, 60])
    XCTAssertEqual(points.map(\.highestWPM), [0, 51, 0, 60])
    XCTAssertEqual(points.map(\.averageAccuracy), [0, 85.5, 0, 90])
    XCTAssertEqual(points.map(\.averageConsistency), [0, 80, 0, 50])
    XCTAssertEqual(points.map(\.restartsPerCompletedTest), [0, 1.5, 0, 0])
    XCTAssertEqual(
      points.map(\.day),
      [
        end.addingTimeInterval(-259_200),
        end.addingTimeInterval(-172_800),
        end.addingTimeInterval(-86_400),
        end,
      ])
  }

  func testActivityBarSelectionChoosesNearestCalendarPointAndRejectsEmptyInput() {
    let start = Date(timeIntervalSince1970: 86_400)
    let points = [
      ActivityBarPoint(day: start, completedTests: 1, typingSeconds: 30),
      ActivityBarPoint(
        day: start.addingTimeInterval(86_400), completedTests: 2, typingSeconds: 90),
      ActivityBarPoint(
        day: start.addingTimeInterval(172_800), completedTests: 0, typingSeconds: 0),
    ]

    XCTAssertEqual(
      ActivityBarSelectionPolicy.nearestPoint(
        to: start.addingTimeInterval(60_000), in: points)?.day,
      start.addingTimeInterval(86_400))
    XCTAssertEqual(
      ActivityBarSelectionPolicy.nearestPoint(
        to: start.addingTimeInterval(43_200), in: points)?.day,
      start)
    XCTAssertNil(ActivityBarSelectionPolicy.nearestPoint(to: start, in: []))
  }

  func testTypingMinutesTrendUsesOnlyObservedDaysAndTheirCalendarSpacing() throws {
    let start = Date(timeIntervalSince1970: 86_400)
    let points = [
      ActivityBarPoint(day: start, completedTests: 1, typingSeconds: 60),
      ActivityBarPoint(
        day: start.addingTimeInterval(86_400), completedTests: 1, typingSeconds: 120),
      ActivityBarPoint(
        day: start.addingTimeInterval(172_800), completedTests: 0, typingSeconds: 0),
      ActivityBarPoint(
        day: start.addingTimeInterval(259_200), completedTests: 1, typingSeconds: 240),
      ActivityBarPoint(
        day: start.addingTimeInterval(345_600), completedTests: 1, typingSeconds: .infinity),
    ].reversed()

    let trend = ActivityTypingMinutesTrendPolicy.points(for: Array(points))

    XCTAssertEqual(trend.map(\.day), [start, start.addingTimeInterval(259_200)])
    XCTAssertEqual(try XCTUnwrap(trend.first).minutes, 1, accuracy: 0.000_001)
    XCTAssertEqual(try XCTUnwrap(trend.last).minutes, 4, accuracy: 0.000_001)
    XCTAssertTrue(ActivityTypingMinutesTrendPolicy.points(for: []).isEmpty)
    XCTAssertTrue(ActivityTypingMinutesTrendPolicy.points(for: [points.last!]).isEmpty)
    XCTAssertTrue(
      ActivityTypingMinutesTrendPolicy.points(for: [
        ActivityBarPoint(day: start, completedTests: 1, typingSeconds: 60),
        ActivityBarPoint(day: start, completedTests: 1, typingSeconds: 120),
      ]).isEmpty)
  }

  func testCurrentStreakOnlyCountsConsecutiveDaysEndingToday() {
